  it("test_edgeql_expr_coalesce_01", () => {
    assertQueryResult(
      h,
      `SELECT <int64>{} ?? 4 ?? 5;`,
      [4]
    );
    assertQueryResult(
      h,
      `SELECT <str>{} ?? 'foo' ?? 'bar';`,
      ["foo"]
    );
    assertQueryResult(
      h,
      `SELECT 4 ?? <int64>{} ?? 5;`,
      [4]
    );
    assertQueryResult(
      h,
      `SELECT 'foo' ?? <str>{} ?? 'bar';`,
      ["foo"]
    );
    assertQueryResult(
      h,
      `SELECT <str>{} ?? 'bar' = 'bar';`,
      [true]
    );
    assertQueryResult(
      h,
      `SELECT 4^<int64>{} ?? 2;`,
      [2]
    );
    assertQueryResult(
      h,
      `SELECT 4+<int64>{} ?? 2;`,
      [6]
    );
    assertQueryResult(
      h,
      `SELECT 4*<int64>{} ?? 2;`,
      [8]
    );
    assertQueryResult(
      h,
      `SELECT -<int64>{} ?? 2;`,
      [2]
    );
    assertQueryResult(
      h,
      `SELECT -<int64>{} ?? -2 + 1;`,
      [-1]
    );
    assertQueryResult(
      h,
      `SELECT <int64>{} ?? <int64>{};`,
      []
    );
    assertQueryResult(
      h,
      `SELECT <int64>{} ?? <int64>{} ?? <int64>{};`,
      []
    );
  });

  it("test_edgeql_expr_string_01", () => {
    assertQueryResult(
      h,
      `SELECT 'qwerty';`,
      ["qwerty"]
    );
    assertQueryResult(
      h,
      `SELECT 'qwerty'[2];`,
      ["e"]
    );
    assertQueryResult(
      h,
      `SELECT 'qwerty'[-2];`,
      ["t"]
    );
    assertQueryResult(
      h,
      `SELECT 'qwerty'[2:4];`,
      ["er"]
    );
    assertQueryResult(
      h,
      `SELECT 'qwerty'[2:];`,
      ["erty"]
    );
    assertQueryResult(
      h,
      `SELECT 'qwerty'[:2];`,
      ["qw"]
    );
    assertQueryResult(
      h,
      `SELECT 'qwerty'[2:-1];`,
      ["ert"]
    );
    assertQueryResult(
      h,
      `SELECT 'qwerty'[-2:];`,
      ["ty"]
    );
    assertQueryResult(
      h,
      `SELECT 'qwerty'[:-2];`,
      ["qwer"]
    );
    assertQueryResult(
      h,
      `SELECT 'qwerty'[<int16>2];`,
      ["e"]
    );
    assertQueryResult(
      h,
      `SELECT 'qwerty'[<int32>2];`,
      ["e"]
    );
  });

  it("test_edgeql_expr_string_02", () => {
    expect(() => {
      h.query(
        `
                SELECT '123'['1'];
            `
      );
    }).toThrow(new RegExp("cannot index string by.*str"));
  });

