  it("test_edgeql_expr_tuple_02", () => {
    assertQueryResult(
      h,
      `SELECT (1, 'foo') = (1, 'foo');`,
      [true]
    );
    assertQueryResult(
      h,
      `SELECT (1, 'foo') = (2, 'foo');`,
      [false]
    );
    assertQueryResult(
      h,
      `SELECT (1, 'foo') != (1, 'foo');`,
      [false]
    );
    assertQueryResult(
      h,
      `SELECT (1, 'foo') != (2, 'foo');`,
      [true]
    );
    assertQueryResult(
      h,
      `SELECT (1, 2) = (1, 2.0);`,
      [true]
    );
    assertQueryResult(
      h,
      `SELECT (1, 2.0) = (1, 2);`,
      [true]
    );
    assertQueryResult(
      h,
      `SELECT (1, 2.1) != (1, 2);`,
      [true]
    );
  });

