  it("test_edgeql_expr_range_29", () => {
    for (const [_, desc0] of (get_test_items({anyreal: true}) as any)) {
      let t0 = desc0.typename;
      for (const [_, desc1] of (get_test_items({anyreal: true}) as any)) {
        let t1 = desc1.typename;
        let query = `
                    with r := range(2, 9)
                    select count(
                        (
                            <range<${t0}>><range<${t1}>>r,
                            <multirange<${t0}>><multirange<${t1}>>
                                multirange([r]),
                            <multirange<${t0}>><range<${t0}>>r,
                        )
                    );
                `;
        if ([t0, t1].every((t) => ["decimal", "float32", "float64", "int32", "int64"].includes(t))) {
          assertQueryResult(
            h,
            query,
            [1]
          );
          query = `
                        with r := range(<${t1}>{}, empty := true)
                        select (
                            range_is_empty(
                                <range<${t0}>>r
                            ),
                            range_is_empty(
                                <multirange<${t1}>>r
                            ),
                            range_is_empty(
                                <multirange<${t0}>>multirange(
                                    <array<range<${t1}>>>[]
                                )
                            ),
                        );
                    `;
          assertQueryResult(
            h,
            query,
            [
                  [true, true, true],
                ]
          );
        } else {
          expect(() => {
            h.query(
              query
            );
          }).toThrow(new RegExp("unsupported range subtype"));
        }
      }
    }
  });

