  it("test_edgeql_expr_range_34", () => {
    assertQueryResult(
      h,
      `
                select <range<int64>>to_json('{
                    "lower": 2,
                    "inc_lower": true,
                    "upper": 10,
                    "inc_upper": true
                }') = range(2, 11);
            `,
      [true]
    );
    assertQueryResult(
      h,
      `
                select <range<int64>>to_json('{
                    "lower": null,
                    "inc_lower": true,
                    "upper": 10,
                    "inc_upper": false
                }') = range(<int64>{}, 10);
            `,
      [true]
    );
    assertQueryResult(
      h,
      `
                select <range<int64>>to_json('{
                    "lower": 2,
                    "inc_lower": true,
                    "inc_upper": false
                }') = range(2);
            `,
      [true]
    );
    expect(() => {
      h.script(
        `
                select <range<int32>>to_json('{
                    "lower": 2,
                    "inc_lower": true,
                    "upper": 2147483648,
                    "inc_upper": false
                }');
            `
      );
    }).toThrow(new RegExp("\"2147483648\" is out of range for type std::int32"));
    expect(() => {
      h.script(
        `
                select <range<int64>>to_json('{
                    "lower": 2,
                    "inc_lower": true,
                    "upper": 9223372036854775808,
                    "inc_upper": false
                }');
            `
      );
    }).toThrow(new RegExp("\"9223372036854775808\" is out of range for type std::int64"));
    expect(() => {
      h.script(
        `
                select <range<float32>>to_json('{
                    "lower": 2,
                    "inc_lower": true,
                    "upper": 1e100,
                    "inc_upper": false
                }');
            `
      );
    }).toThrow(new RegExp(".+ is out of range for type std::float32"));
    expect(() => {
      h.script(
        `
                select <range<float64>>to_json('{
                    "lower": 2,
                    "inc_lower": true,
                    "upper": 1e500,
                    "inc_upper": false
                }');
            `
      );
    }).toThrow(new RegExp(".+ is out of range for type std::float64"));
    expect(() => {
      h.script(
        `
                select <range<int64>>to_json('{
                    "lower": "2",
                    "inc_lower": true,
                    "upper": 10,
                    "inc_upper": false
                }');
            `
      );
    }).toThrow(new RegExp("expected JSON number or null; got JSON string"));
    expect(() => {
      h.script(
        `
                select <range<int64>>to_json('{
                    "lower": 2.5,
                    "inc_lower": true,
                    "upper": 10,
                    "inc_upper": false
                }');
            `
      );
    }).toThrow(new RegExp("invalid input syntax for type std::int64: \"2.5\""));
    expect(() => {
      h.script(
        `
                select <range<int64>>to_json('{
                    "lower": 2,
                    "inc_lower": true,
                    "upper": 10,
                    "inc_upper": null
                }');
            `
      );
    }).toThrow(new RegExp("JSON object representing a range must include an 'inc_upper' boolean property"));
    expect(() => {
      h.script(
        `
                select <range<int64>>to_json('{
                    "lower": 2,
                    "upper": 10,
                    "inc_upper": false
                }');
            `
      );
    }).toThrow(new RegExp("JSON object representing a range must include an 'inc_lower' boolean property"));
    expect(() => {
      h.script(
        `
                select <range<int64>>to_json('["bad", null]');
            `
      );
    }).toThrow(new RegExp("expected JSON object or null; got JSON array"));
    expect(() => {
      h.script(
        `
                select <range<int64>>to_json('{"bad": null}');
            `
      );
    }).toThrow(new RegExp("JSON object representing a range must include an 'inc_lower' boolean property"));
    expect(() => {
      h.script(
        `
                select <range<int64>>to_json('"bad"');
            `
      );
    }).toThrow(new RegExp("expected JSON object or null; got JSON string"));
    expect(() => {
      h.script(
        `
                select <range<int64>>to_json('1312');
            `
      );
    }).toThrow(new RegExp("expected JSON object or null; got JSON number"));
    expect(() => {
      h.script(
        `
                select <range<int64>>to_json('true');
            `
      );
    }).toThrow(new RegExp("expected JSON object or null; got JSON boolean"));
    expect(() => {
      h.script(
        `
                select <range<cal::local_date>>to_json('{
                    "lower": "2022.06.10",
                    "inc_lower": true,
                    "upper": "2022-06-17",
                    "inc_upper": false
                }');
            `
      );
    }).toThrow(new RegExp("invalid input syntax for type std::cal::local_date: '2022.06.10'"));
    expect(() => {
      h.script(
        `
                select <range<cal::local_date>>to_json('{
                    "lower": "2022-06-10",
                    "inc_lower": true,
                    "upper": "12022-06-17",
                    "inc_upper": false
                }');
            `
      );
    }).toThrow(new RegExp("invalid input syntax for type std::cal::local_date: '12022-06-17'"));
    assertQueryResult(
      h,
      `
                select range_is_empty(<range<int64>>to_json('{
                    "empty": true
                }'))
            `,
      [true]
    );
  });

