  it("test_edgeql_expr_if_else_01", () => {
    assertQueryResult(
      h,
      `SELECT IF true THEN 'yes' ELSE 'no';`,
      ["yes"]
    );
    assertQueryResult(
      h,
      `SELECT IF false THEN 'yes' ELSE 'no';`,
      ["no"]
    );
    assertQueryResult(
      h,
      `SELECT 'yes' IF True ELSE 'no';`,
      ["yes"]
    );
    assertQueryResult(
      h,
      `SELECT 'yes' IF 1=1 ELSE 'no';`,
      ["yes"]
    );
    assertQueryResult(
      h,
      `SELECT 'yes' IF 1=0 ELSE 'no';`,
      ["no"]
    );
    assertQueryResult(
      h,
      `SELECT 's1' IF 1=0 ELSE 's2' IF 2=2 ELSE 's3';`,
      ["s2"]
    );
  });

  it("test_edgeql_expr_if_else_02", () => {
    assertQueryResult(
      h,
      `SELECT 'yes' IF True ELSE {'no', 'or', 'maybe'};`,
      ["yes"]
    );
    assertQueryResult(
      h,
      `SELECT 'yes' IF False ELSE {'no', 'or', 'maybe'};`,
      ["no", "or", "maybe"]
    );
    assertQueryResult(
      h,
      `SELECT {'maybe', 'yes'} IF True ELSE {'no', 'or'};`,
      ["maybe", "yes"]
    );
    assertQueryResult(
      h,
      `SELECT {'maybe', 'yes'} IF False ELSE {'no', 'or'};`,
      ["no", "or"]
    );
    assertQueryResult(
      h,
      `SELECT {'maybe', 'yes'} IF True ELSE 'no';`,
      ["maybe", "yes"]
    );
    assertQueryResult(
      h,
      `SELECT {'maybe', 'yes'} IF False ELSE 'no';`,
      ["no"]
    );
    assertQueryResult(
      h,
      `SELECT 'yes' IF {True, False} ELSE 'no';`,
      ["yes", "no"]
    );
    assertQueryResult(
      h,
      `SELECT 'yes' IF {True, False} ELSE {'no', 'or', 'maybe'};`,
      ["yes", "no", "or", "maybe"]
    );
    assertQueryResult(
      h,
      `SELECT {'maybe', 'yes'} IF {True, False} ELSE {'no', 'or'};`,
      ["maybe", "yes", "no", "or"]
    );
    assertQueryResult(
      h,
      `SELECT {'maybe', 'yes'} IF {True, False} ELSE 'no';`,
      ["maybe", "yes", "no"]
    );
  });

  it("test_edgeql_expr_if_else_03", () => {
    assertQueryResult(
      h,
      `SELECT 1 IF {1, 2, 3} < {2, 3, 4} ELSE 100;`,
      unorderedBag([
            1,
            1,
            1,
            1,
            1,
            1,
            100,
            100,
            100,
          ])
    );
    assertQueryResult(
      h,
      `SELECT {1, 10} IF {1, 2, 3} < {2, 3, 4} ELSE 100;`,
      unorderedBag([
            1,
            1,
            1,
            1,
            1,
            1,
            10,
            10,
            10,
            10,
            10,
            10,
            100,
            100,
            100,
          ])
    );
    assertQueryResult(
      h,
      `SELECT sum(1 IF {1, 2, 3} < {2, 3, 4} ELSE 100);`,
      unorderedBag([306])
    );
    assertQueryResult(
      h,
      `SELECT sum({1, 10} IF {1, 2, 3} < {2, 3, 4} ELSE 100);`,
      unorderedBag([366])
    );
  });

  it("test_edgeql_expr_if_else_04", () => {
    assertQueryResult(
      h,
      `
                WITH x := <str>{}
                SELECT
                    1   IF x = 'a' ELSE
                    10  IF x = 'b' ELSE
                    100 IF x = 'c' ELSE
                    0;
            `,
      unorderedBag([])
    );
    assertQueryResult(
      h,
      `
                WITH x := {'c', 'a', 't'}
                SELECT
                    1   IF x = 'a' ELSE
                    10  IF x = 'b' ELSE
                    100 IF x = 'c' ELSE
                    0;
            `,
      unorderedBag([0, 1, 100])
    );
    assertQueryResult(
      h,
      `
                WITH x := {'b', 'a', 't'}
                SELECT
                    1   IF x = 'a' ELSE
                    10  IF x = 'b' ELSE
                    100 IF x = 'c' ELSE
                    0;
            `,
      unorderedBag([0, 1, 10])
    );
    assertQueryResult(
      h,
      `
                WITH x := {'b', 'a', 't'}
                SELECT
                    IF x = 'a' THEN 1 ELSE
                    IF x = 'b' THEN 10 ELSE
                    IF x = 'c' THEN 100 ELSE
                    0;
            `,
      unorderedBag([0, 1, 10])
    );
    assertQueryResult(
      h,
      `
                FOR w IN {<array<str>>[], ['c', 'a', 't'], ['b', 'a', 't']}
                UNION (
                    WITH x := array_unpack(w)
                    SELECT sum(
                        1   IF x = 'a' ELSE
                        10  IF x = 'b' ELSE
                        100 IF x = 'c' ELSE
                        0
                    )
                );
            `,
      unorderedBag([0, 11, 101])
    );
  });

