  it("test_edgeql_assert_exists_01", () => {
    h.script(
      `
            INSERT User {
                name := "User 1",
            };
            INSERT User {
                name := "User 2",
            }
        `
    );
    assertQueryResult(
      h,
      `
                SELECT assert_exists((
                    SELECT User { name } FILTER .name IN {"User 1", "User 2"}
                )) ORDER BY .name
            `,
      [
            {
              "name": "User 1",
            },
            {
              "name": "User 2",
            },
          ]
    );
    assertQueryResult(
      h,
      `
                SELECT {
                    user := assert_exists(
                        (SELECT User FILTER .name = "User 1").name
                    )
                }
            `,
      [
            {
              "user": "User 1",
            },
          ]
    );
    assertQueryResult(
      h,
      `
                SELECT {
                    required user := assert_exists(
                        (SELECT User FILTER .name = "User 1").name
                    )
                }
            `,
      [
            {
              "user": "User 1",
            },
          ]
    );
    h.query(
      `
                SELECT {
                    required all_users := assert_exists(User)
                }
            `
    );
    expect(() => {
      h.query(
        `
                SELECT assert_exists(<str>{});
            `
      );
    }).toThrow(new RegExp("assert_exists violation"));
    expect(() => {
      h.query(
        `
                SELECT assert_exists(
                    (SELECT User FILTER .name = "nonexistent")
                );
            `
      );
    }).toThrow(new RegExp("assert_exists violation"));
    expect(() => {
      h.query(
        `
                SELECT User {
                    bff := assert_exists((
                        SELECT User FILTER .name = "nonexistent"))
                }
                FILTER .name = "User 2";
            `
      );
    }).toThrow(new RegExp("assert_exists violation"));
    expect(() => {
      h.query("\n                SELECT assert_exists(\n                    (SELECT User { name } FILTER .name = \"nonexistent\")\n                );\n            ");
    }).toThrow(new RegExp("assert_exists violation"));
    expect(() => {
      h.query(
        `
                SELECT assert_exists(
                    (SELECT User FILTER .name = "nonexistent")
                ).name;
            `
      );
    }).toThrow(new RegExp("assert_exists violation"));
    expect(() => {
      h.query(
        `
                SELECT assert_exists(
                    (SELECT User FILTER .name = "nonexistent"),
                    message := "custom message",
                ).name;
            `
      );
    }).toThrow(new RegExp("custom message"));
    expect(() => {
      h.query(
        `
                with x := assert_exists(
                    (select {(1, 2), (3, 4)} filter false)),
                select x.0;
            `
      );
    }).toThrow(new RegExp("assert_exists violation"));
  });

