  it("test_edgeql_expr_str_interpolation_01", () => {
    assertQueryResult(
      h,
      `
                select "1 + 1 = \\(1 + 1)"
            `,
      ["1 + 1 = 2"]
    );
    assertQueryResult(
      h,
      `
                select ("1 + 1 = \\(1 + 1)")
            `,
      ["1 + 1 = 2"]
    );
    assertQueryResult(
      h,
      `select "asdf \\(str_reverse("1234") ++
"[\\(sum({1,2,3}))]")! count(User)=\\
\\(
count(User))" ++ "!";`,
      ["asdf 4321[6]! count(User)=0!"]
    );
  });
